```c
int buffer[MAX];
int fill = 0;
int use = 0;

void put(int value) {
    buffer[fill] = value;      // f1
    fill = (fill + 1) % MAX;   // f2
}

int get() {
    int tmp = buffer[use];     // g1
    use = (use + 1) % MAX;     // g2
    return tmp;
}
```

`put()` 先写入 `buffer[fill]` 再推进 `fill`；`get()` 先读出 `buffer[use]` 再推进 `use`。两个索引都以 MAX 取模，所以缓冲区被当作环形数组复用。

```c
sem_t empty;
sem_t full;

void *producer(void *arg) {
    for (int i = 0; i < loops; i++) {
        sem_wait(&empty);   // P1
        put(i);             // P2
        sem_post(&full);    // P3
    }
}

void *consumer(void *arg) {
    int tmp = 0;
    while (tmp != -1) {
        sem_wait(&full);    // C1
        tmp = get();        // C2
        sem_post(&empty);   // C3
        printf("%d\n", tmp);
    }
}

int main(int argc, char *argv[]) {
    sem_init(&empty, 0, MAX);  // 初始有 MAX 个空槽
    sem_init(&full, 0, 0);     // 初始有 0 个满槽
}
```

教材先假设 MAX = 1 验证：消费者先运行，`sem_wait(&full)` 把 full 从 0 减为 -1 并睡眠；生产者执行 `sem_wait(&empty)` 成功，放入数据后 `sem_post(&full)` 唤醒消费者。之后无论生产者继续循环而被 empty 阻塞，还是消费者取走数据，都符合预期。

```c
sem_t empty;
sem_t full;
sem_t mutex;

void *producer(void *arg) {
    for (int i = 0; i < loops; i++) {
        sem_wait(&mutex);  // p0 新增
        sem_wait(&empty);  // p1
        put(i);            // p2
        sem_post(&full);   // p3
        sem_post(&mutex);  // p4 新增
    }
}

void *consumer(void *arg) {
    for (int i = 0; i < loops; i++) {
        sem_wait(&mutex);  // c0 新增
        sem_wait(&full);   // c1
        int tmp = get();   // c2
        sem_post(&empty);  // c3
        sem_post(&mutex);  // c4 新增
        printf("%d\n", tmp);
    }
}
```

教材把整个 `put()`/`get()` 序列都放进互斥量，`mutex` 初值为 1。看起来所有共享访问都被保护了，但这一版仍然有问题。

```c
sem_t empty;
sem_t full;
sem_t mutex;

void *producer(void *arg) {
    for (int i = 0; i < loops; i++) {
        sem_wait(&empty);   // p1
        sem_wait(&mutex);   // p1.5
        put(i);             // p2
        sem_post(&mutex);   // p2.5
        sem_post(&full);    // p3
    }
}

void *consumer(void *arg) {
    for (int i = 0; i < loops; i++) {
        sem_wait(&full);    // c1
        sem_wait(&mutex);   // c1.5
        int tmp = get();    // c2
        sem_post(&mutex);   // c2.5
        sem_post(&empty);   // c3
        printf("%d\n", tmp);
    }
}

int main(int argc, char *argv[]) {
    sem_init(&empty, 0, MAX);
    sem_init(&full, 0, 0);
    sem_init(&mutex, 0, 1);
}
```

解决方法是减少锁的作用域：把获取和释放互斥量的操作调整为紧挨着临界区，把 `full`、`empty` 的等待和唤醒放到锁外。这样得到简单而有效的有界缓冲区，也是多线程程序的常用模式。
